<script lang="ts">
 import {tick,onDestroy} from 'svelte';import {invalidateAll} from '$app/navigation';import 'leaflet/dist/leaflet.css';
 let {model,t,canEdit}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string;canEdit:boolean}=$props();let container=$state<HTMLDivElement>();let map:import('leaflet').Map|undefined;let lib:typeof import('leaflet')|undefined;let previewLayer:import('leaflet').Polygon|undefined;let opened=$state(false),vineyard=$state(''),coordinates=$state<[number,number][]>([]),drawing=$state(false),busy=$state(false),message=$state('');
 async function open(){opened=true;await tick();lib=await import('leaflet');map=lib.map(container!).setView([49.8,8.2],11);lib.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(map);const bounds=lib.latLngBounds([]);for(const v of model.vineyards){if(!v.geometry)continue;const label=document.createElement('span');label.textContent=v.code+' · '+v.name;const layer=lib.geoJSON(v.geometry).bindTooltip(label).addTo(map);bounds.extend(layer.getBounds());}if(bounds.isValid())map.fitBounds(bounds);map.on('click',e=>{if(!drawing)return;coordinates=[...coordinates,[e.latlng.lng,e.latlng.lat]];draw();});}
 function draw(){if(!map||!lib)return;previewLayer?.remove();previewLayer=lib.polygon(coordinates.map(([lon,lat])=>[lat,lon]),{color:'#a65e20'}).addTo(map);}
 async function file(event:Event){const selected=(event.currentTarget as HTMLInputElement).files?.[0];if(!selected||selected.size>1000000)return;try{const json=JSON.parse(await selected.text());const geometry=json.type==='FeatureCollection'?json.features[0]?.geometry:json.type==='Feature'?json.geometry:json;if(geometry.type!=='Polygon')throw new Error('INVALID_GEOMETRY');coordinates=geometry.coordinates[0].slice(0,-1);draw();}catch{message=t('INVALID_GEOMETRY');}}
 async function save(){const parcel=model.vineyards.find(v=>v.id===vineyard);if(!parcel||coordinates.length<3)return;busy=true;try{const res=await fetch('/api/commands',{method:'POST',headers:{'content-type':'application/json','idempotency-key':crypto.randomUUID()},body:JSON.stringify({type:'vineyard_geometry',vineyard_id:vineyard,expected_version:parcel.version,geometry:{type:'Polygon',coordinates:[[...coordinates,coordinates[0]]]}})});message=res.ok?t('saved'):t((await res.json()).message);if(res.ok){drawing=false;await invalidateAll();}}catch{message=t('connectionError');}finally{busy=false;}}
 onDestroy(()=>map?.remove());
</script>
<section class="card"><h2>{t('parcelMap')}</h2>{#if !opened}<p class="muted">{t('mapConsent')}</p><button onclick={open}>{t('openMap')}</button>{:else}<div class="map" bind:this={container}></div>{#if canEdit}<label>{t('vineyard_id')}<select bind:value={vineyard}><option value="">—</option>{#each model.vineyards as v}<option value={v.id}>{v.code} · {v.name}</option>{/each}</select></label><div class="actions"><button onclick={()=>{drawing=!drawing;coordinates=[];draw();}}>{drawing?t('stopDrawing'):t('drawPolygon')}</button><button onclick={()=>{coordinates=coordinates.slice(0,-1);draw();}}>{t('undoPoint')}</button><button onclick={save} disabled={busy||!vineyard||coordinates.length<3}>{t('saveGeometry')}</button></div><label>GeoJSON<input type="file" accept=".json,.geojson" onchange={file} /></label><p class="muted">{t('geometryHint')}</p>{/if}{/if}<p role="status">{message}</p></section>
<style>.map{height:420px;width:100%;z-index:0;border-radius:8px;margin-bottom:18px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}@media(max-width:600px){.map{height:300px}}</style>
